function beta_so_fail(string $msg, int $code = 400): void {
    while (ob_get_level() > 0) { ob_end_clean(); }
    http_response_code($code); header('Content-Type: application/json');
    echo json_encode(['success' => false, 'error' => $msg]); exit();
}
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!isset($_POST['save_socials'])) beta_so_fail('Unknown action.');
    foreach ($platforms as $bP) {
        $bH = (string) ($_POST[$bP . '_handle'] ?? '');
        if (mb_strlen(trim($bH)) > 255) beta_so_fail('Handles must be 255 characters or fewer.');
        if (preg_match('/[\x00-\x1F\x7F]/', $bH)) beta_so_fail('Handles cannot contain line breaks or control characters.');
        if (isset($_POST[$bP . '_active']) && ((string) $_POST[$bP . '_active'] !== '1' || trim($bH) === '')) beta_so_fail('Only a platform with a handle can be shown.');
    }
    foreach (array_keys($_POST) as $bK) if ($bK !== 'save_socials' && !preg_match('/^(' . implode('|', $platforms) . ')_(handle|active)$/', $bK)) beta_so_fail('Unknown field.');
}
// Handle saving
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['save_socials'])) {
    while (ob_get_level()) { ob_end_clean(); }
    header('Content-Type: application/json');
    
    $success = true;
    $db->begin_transaction();
    try {
        foreach ($platforms as $displayOrder => $platform) {
            $handle = trim($_POST[$platform . '_handle'] ?? '');
            $isActive = isset($_POST[$platform . '_active']) ? 1 : 0;
            
            // Only update or insert if the handle is not empty, otherwise delete or mark inactive
            if ($handle === '') {
                $stmt = $db->prepare("DELETE FROM user_socials WHERE platform = ?");
                $stmt->bind_param("s", $platform);
                $stmt->execute();
                $stmt->close();
            } else {
                $stmt = $db->prepare("INSERT INTO user_socials (platform, handle, is_active, display_order) VALUES (?, ?, ?, ?) ON DUPLICATE KEY UPDATE handle = VALUES(handle), is_active = VALUES(is_active), display_order = VALUES(display_order)");
                $stmt->bind_param("ssii", $platform, $handle, $isActive, $displayOrder);
                $stmt->execute();
                $stmt->close();
            }
        }
        $db->commit();
        echo json_encode(['success' => true]);
    } catch (Exception $e) {
        $db->rollback();
        error_log('beta socials save: ' . $e->getMessage());
        echo json_encode(['success' => false, 'error' => 'Could not save your socials. Try again.']);
    }
    exit();
}

